-- Fix: V4 created `discussions` WITHOUT the identity generation on id — the entity declares
-- @GeneratedValue(IDENTITY), but on the Flyway-owned schema (live Postgres) inserts then fail
-- with "null value in column id violates not-null constraint" (H2 tests never see it: the
-- test profile regenerates the schema FROM the entities). V4 is already applied on live
-- databases, so the fix ships as V5 rather than an in-place edit (Flyway checksum).
-- The table is empty at this point (creation always failed), so no backfill is involved.
ALTER TABLE discussions ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.discussions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
